package glitch

import data.glitch_lib

sensitive_keywords := {"password", "passwd", "pwd", "secret", "token", "access_key", "api_key", "admin_password", "db_password", "root_password", "default_password", "key", "sha512_password"}

connection_string_patterns := [
    `(?i)["'][A-Za-z0-9!@#$%^&*()_+\-=\[\]{};':"\\|,.<>?]*?(?:password|pwd)["']\s*[=:]\s*["'][^"'\n]{3,}["']`,
    `(?i)(?:secret|password|token)\s*[=:]\s*["'][^"'\n]{3,}["']`
]

find_sensitive_keys(node) = results {
    results = walk_and_find_sensitive(node, [])
}

walk_and_find_sensitive(node, acc) = results {
    node.ir_type == "Hash"
    kv = node.value[_]
    key_name = lower(kv.name)
    value_expr = kv.value
    new_acc = acc | {{"key": key_name, "value": value_expr}}
    results = new_acc
}

walk_and_find_sensitive(node, acc) = results {
    node.ir_type == "Array"
    item = node.value[_]
    results = walk_and_find_sensitive(item, acc)
} else {
    node.ir_type == "Hash"
    inner_item = node.value[_]
    inner_item.value.ir_type == "Hash"
    results = walk_and_find_sensitive(inner_item.value, acc)
} else {
    node.ir_type == "Hash"
    inner_item = node.value[_]
    inner_item.value.ir_type == "Array"
    results = walk_and_find_sensitive(inner_item.value, acc)
} else {
    results = acc
}

